module old_resource_names;
// Ordinary identifiers under actual source language0.20.
pub fn resource_close(x:i64)->i64{return x+1;}
pub fn resource_is_open(x:i64)->bool{return x==41;}
fn note()->str{return "resource_close and resource_is_open";}
fn solve()->i64{if resource_is_open(41){return resource_close(41);}return 0;}
fn main()->unit!{io}{print(solve());}
test fn check_old_names()->unit{assert(solve()==42);assert(note()=="resource_close and resource_is_open");}
